import{_ as t,o as e,c as p,a0 as o}from"./chunks/framework.jwovEGr5.js";const l="/assets/%E6%95%B0%E6%8D%AE%E7%BA%BF.B2DrRE8Y.png",i="/assets/%E5%9B%BE%E7%89%87%E6%A0%BC%E5%BC%8F1.CGWNIxyk.jpg",r="/assets/%E5%9B%BE%E7%89%87%E6%A0%BC%E5%BC%8F2.DydUSJE3.jpg",x=JSON.parse('{"title":"图片传输","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"电脑知识/图片传输.md","filePath":"电脑知识/图片传输.md"}'),s={name:"电脑知识/图片传输.md"};function c(n,a,d,h,m,_){return e(),p("div",null,[...a[0]||(a[0]=[o('<h1 id="图片传输" tabindex="-1">图片传输 <a class="header-anchor" href="#图片传输" aria-label="Permalink to &quot;图片传输&quot;">​</a></h1><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><ol><li>准备数据线</li></ol><p>一般情况下你的充电线就是一根数据线，但确实有的只有充电功能，没有数据线路。优先使用手机原装数据线。</p><p><img src="'+l+'" alt="数据线" width="200px"></p><ol start="2"><li><p>数据线一头插手机Type-C口，另一头直接插电脑主板USB口（台式机优先机箱后面接口）</p></li><li><p>USB连接选项</p></li></ol><p>一般情况下，打开手机就会直接在下方显示链接选项，且默认为<code>仅充电</code></p><p>你也可以从手机屏幕顶部往下拉开通知栏，找到通知：通过USB为设备充电，点击这条通知，打开USB连接选项</p><ol start="4"><li>点击<code>仅传输照片</code>选项，此时你的电脑可以访问手机相册</li></ol><blockquote><p>你的手机也仍在充电中（一边充电一边传输）</p></blockquote><ol start="5"><li>桌面打开电脑<code>此电脑</code>（Windows+e），找到你的手机（例如<code>荣耀畅玩</code>），里面会出现DCIM等文件夹，剪切到我们的电脑即可</li></ol><h2 id="可能出现的问题" tabindex="-1">可能出现的问题 <a class="header-anchor" href="#可能出现的问题" aria-label="Permalink to &quot;可能出现的问题&quot;">​</a></h2><h3 id="只有充电选项" tabindex="-1">只有充电选项 <a class="header-anchor" href="#只有充电选项" aria-label="Permalink to &quot;只有充电选项&quot;">​</a></h3><ol><li>更换数据线（大概率是充电专用线）</li><li>换电脑上另外一个USB接口</li></ol><h2 id="小知识" tabindex="-1">小知识 <a class="header-anchor" href="#小知识" aria-label="Permalink to &quot;小知识&quot;">​</a></h2><h3 id="dcim-pictures" tabindex="-1">DCIM &amp; Pictures <a class="header-anchor" href="#dcim-pictures" aria-label="Permalink to &quot;DCIM &amp; Pictures&quot;">​</a></h3><p>DCIM就是Digital Camera Images（数字相机图像）</p><p>是你亲手用相机拍摄的原图/原视频</p><p>而Pictures是非相机拍摄的各类图片</p><p>例如截图、网上保存图片、软件下载、表情包、修图后的副本。</p><blockquote><p>当然凡事都是有特例的</p></blockquote><h3 id="一些文件介绍" tabindex="-1">一些文件介绍 <a class="header-anchor" href="#一些文件介绍" aria-label="Permalink to &quot;一些文件介绍&quot;">​</a></h3><p>如下图</p><p><img src="'+i+'" alt="图片格式1"></p><ol><li><strong>cache文件夹</strong></li></ol><p>cache是缓存文件夹，相机APP运行时自动生成，存放图片预览图、处理过程临时素材、缩略图缓存。</p><p>可以删除；删掉后图库加载图片会稍微慢一点，打开相机后系统会自动重建缓存。</p><ol start="2"><li><strong>.inside（0字节空文件）</strong></li></ol><p>这类0KB隐藏空文件，是相机应用生成的标记/锁文件。</p><p>作用：标记文件夹状态、防止进程冲突。文件里面没有任何数据。</p><ol start="3"><li><strong>IMG_xxxx.jpg.tmp文件</strong></li></ol><p>.tmp是Temporary临时文件</p><p>产生原因：</p><ol><li>拍照瞬间发生中断</li><li>手机拍照时突然锁屏/闪退</li><li>拍照过程存储空间不足</li><li>文件传输中断（手机连电脑拷贝照片中途断开）</li></ol><p>运行逻辑：</p><p>相机先写入临时文件.jpg.tmp，照片完整保存成功后，后缀自动去掉.tmp，变成正常jpg图片。</p><p>所以当保存失败时，就会遗留这个tmp文件。</p><h5 id="tmp两种情况区分" tabindex="-1">.tmp两种情况区分 <a class="header-anchor" href="#tmp两种情况区分" aria-label="Permalink to &quot;.tmp两种情况区分&quot;">​</a></h5><p>那个有大小的tmp文件（例如那个2.92MB的文件）</p><p>可以尝试【重命名】删掉末尾.tmp，变成IMG_xxxx.jpg，看看能不能打开图片，一般来说会有数据损坏。</p><p>0字节的.jpg.tmp文件,完全是空文件，没有任何图像数据，无法恢复。</p><p>更改后如下图</p><p><img src="'+r+'" alt="图片格式2"></p><p>像这种本身大小比较大的，里面的文件损毁较小，只是有点不清晰</p>',44)])])}const B=t(s,[["render",c]]);export{x as __pageData,B as default};
